for row in A[:190]: s.step(row)
print('wine',s.data.xpos[s.model.body('obj_main').id], 'quat',s.data.xquat[s.model.body('obj_main').id], 'eef',s.data.site_xpos[s.model.site('gripper0_left_grip_site').id], flush=True)
for i in range(s.data.ncon):
 c=s.data.contact[i];n1=s.model.geom(c.geom1).name;n2=s.model.geom(c.geom2).name
 if 'gripper0_left' in n1 or 'gripper0_left' in n2:
  if 'obj_' in n1+n2 or 'cabinet' in n1+n2 or 'table' in n1+n2: print('contact',n1,n2,'dist',round(c.dist,4),flush=True)
print('fingers',[(n,round(s.data.qpos[s.model.joint(n).qposadr[0]],3)) for n in [f'gripper0_left_{x}' for x in ['L_pinky_proximal_joint','L_ring_proximal_joint','L_middle_proximal_joint','L_index_proximal_joint','L_thumb_proximal_pitch_joint','L_thumb_proximal_yaw_joint']]],flush=True)
PY
